BEGIN; SET LOCAL statement_timeout='30s'; SET LOCAL lock_timeout='5s';
DO $guard$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' OR current_database()<>'verdify_rehearsal' OR current_setting('cluster_name')<>'verdify-cnpg-s2-integration' OR pg_is_in_recovery() OR (SELECT system_identifier::text FROM pg_control_system())<>'7693399121498484768' OR current_setting('server_version_num')::int<>160013 OR inet_client_addr() IS NOT NULL OR (SELECT oid FROM pg_database WHERE datname=current_database())<>16447 THEN RAISE EXCEPTION 'clone inverse authority refused';END IF; END $guard$;
