DO $guard$ BEGIN IF NOT ((SELECT count(*)=1 AND bool_and(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')='98e97fe60945800835ab1c8a004b957d188aacdc359145433e54ebe3f25ad15b') FROM public.climate_source_events t WHERE event_id='4cc32461-2d38-402e-a97a-75105d9694ce'::uuid) AND (SELECT count(*)=1 AND bool_and(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')='88075da4eab6519e8f16c6c31142eb03aac7fee1e090f48981fc9521fa47a271') FROM public.observational_source_events t WHERE event_id='24e3fbd7-43b2-4676-9873-5ac888db7484'::uuid) AND (SELECT count(*)=1 AND bool_and(encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex')='8ada3869ac9b361e903a19434bbe678350959df1b3b33b5db6a0791268d2fa42') FROM public.equipment_state_source_receipts t WHERE receipt_id='e386f4fe-4c90-42b1-a954-0996ed009304'::uuid) AND EXISTS(SELECT 1 FROM public.climate_source_events WHERE event_id='4cc32461-2d38-402e-a97a-75105d9694ce'::uuid AND greenhouse_id='vallery' AND source_ts='2000-01-01T00:00:00.168626+00:00'::timestamptz AND source_runtime_instance_id='f4d61647-6648-4d8d-a19a-802e07638a7c'::uuid AND source_connection_generation=7 AND climate_payload='{"temp_avg": 70.0}'::jsonb AND sample_provenance='{"temp_avg": {"connection_generation": 7, "received_at": "2000-01-01T00:00:00.168626+00:00", "runtime_instance_id": "f4d61647-6648-4d8d-a19a-802e07638a7c", "source": "s2-qualification"}}'::jsonb) AND EXISTS(SELECT 1 FROM public.observational_source_events WHERE event_id='24e3fbd7-43b2-4676-9873-5ac888db7484'::uuid AND kind='diagnostics' AND greenhouse_id='vallery' AND source_ts='2000-01-01T00:00:00.168626+00:00'::timestamptz AND source_runtime_instance_id='f4d61647-6648-4d8d-a19a-802e07638a7c'::uuid AND source_connection_generation=7 AND event_payload='{"firmware_version": "s2-qualification"}'::jsonb) AND (SELECT count(*)=1 FROM _timescaledb_internal._hyper_1_1109_chunk) AND (SELECT count(*)=1 FROM _timescaledb_internal._hyper_5_1110_chunk) AND (SELECT count(*)=1 FROM _timescaledb_internal._hyper_2_1111_chunk)) OR EXISTS(SELECT 1 FROM public.experiment_v2_outcome_source_bindings WHERE jsonb_path_exists(convert_from(source_bundle_canonical,'UTF8')::jsonb,'$.**.receipt_id ? (@ == $receipt)',jsonb_build_object('receipt','e386f4fe-4c90-42b1-a954-0996ed009304'::text)) OR jsonb_path_exists(convert_from(source_bundle_canonical,'UTF8')::jsonb,'$.**.source_receipt_id ? (@ == $receipt)',jsonb_build_object('receipt','e386f4fe-4c90-42b1-a954-0996ed009304'::text))) OR NOT EXISTS(SELECT 1 FROM public.equipment_state_source_receipts WHERE receipt_id='e386f4fe-4c90-42b1-a954-0996ed009304'::uuid AND source_connection_generation=7 AND source_runtime_instance_id='f4d61647-6648-4d8d-a19a-802e07638a7c'::uuid AND source_observed_through='2000-01-01T00:00:00.168626+00:00'::timestamptz AND gap_requested AND gap_before AND gap_reason='initial_receipt' AND source_sequence=1 AND event_count=1 AND firmware_revision='s2-qualification') THEN RAISE EXCEPTION 'owned fixture/chunk/experiment guard refused'; END IF; END $guard$;
