ALTER TABLE public.equipment_state_source_receipts DISABLE TRIGGER trg_equipment_state_source_receipts_immutable;
DELETE FROM public.equipment_state_source_receipts WHERE receipt_id='e386f4fe-4c90-42b1-a954-0996ed009304'::uuid;
ALTER TABLE public.equipment_state_source_receipts ENABLE TRIGGER trg_equipment_state_source_receipts_immutable;
DELETE FROM public.climate_source_events WHERE event_id='4cc32461-2d38-402e-a97a-75105d9694ce'::uuid;
