DELETE FROM public.climate WHERE ts='2000-01-01T00:00:00.168626+00:00'::timestamptz AND greenhouse_id='vallery' AND temp_avg=70.0;
DELETE FROM public.diagnostics WHERE ts='2000-01-01T00:00:00.168626+00:00'::timestamptz AND greenhouse_id='vallery' AND firmware_version='s2-qualification';
DELETE FROM public.equipment_state WHERE ts='2000-01-01T00:00:00.168626+00:00'::timestamptz AND greenhouse_id='vallery' AND equipment='fan1' AND state=false;
DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.equipment_state_source_receipts'::regclass AND tgname='trg_equipment_state_source_receipts_immutable' AND tgenabled='O' AND encode(sha256(convert_to(pg_get_functiondef(tgfoid),'UTF8')),'hex')='9097ac8f3913fb8fb7fca031fe8649f607943d35cf1b6b10265b11c2018f2d3e') THEN RAISE EXCEPTION 'immutable trigger restoration failed';END IF; END $guard$;
DO $guard$ BEGIN IF EXISTS(SELECT 1 FROM _timescaledb_internal._hyper_1_1109_chunk) THEN RAISE EXCEPTION 'nonempty owned chunk refused';END IF; END $guard$;
DO $guard$ DECLARE dropped text[]; BEGIN SELECT array_agg(x::text ORDER BY x::text) INTO dropped FROM drop_chunks('public.climate'::regclass,older_than=>'2000-01-06T00:00:00+00:00'::timestamptz,newer_than=>'1999-12-30T00:00:00+00:00'::timestamptz) x; IF dropped IS DISTINCT FROM ARRAY['_timescaledb_internal._hyper_1_1109_chunk']::text[] THEN RAISE EXCEPTION 'exact owned drop_chunks set mismatch'; END IF;END $guard$;
