DO $guard$ DECLARE dropped text[]; BEGIN SELECT array_agg(x::text ORDER BY x::text) INTO dropped FROM drop_chunks('public.diagnostics'::regclass,older_than=>'2000-01-06T00:00:00+00:00'::timestamptz,newer_than=>'1999-12-30T00:00:00+00:00'::timestamptz) x; IF dropped IS DISTINCT FROM ARRAY['_timescaledb_internal._hyper_5_1110_chunk']::text[] THEN RAISE EXCEPTION 'exact owned drop_chunks set mismatch'; END IF;END $guard$;
DO $guard$ BEGIN IF EXISTS(SELECT 1 FROM _timescaledb_internal._hyper_2_1111_chunk) THEN RAISE EXCEPTION 'nonempty owned chunk refused';END IF; END $guard$;
DO $guard$ DECLARE dropped text[]; BEGIN SELECT array_agg(x::text ORDER BY x::text) INTO dropped FROM drop_chunks('public.equipment_state'::regclass,older_than=>'2000-01-06T00:00:00+00:00'::timestamptz,newer_than=>'1999-12-30T00:00:00+00:00'::timestamptz) x; IF dropped IS DISTINCT FROM ARRAY['_timescaledb_internal._hyper_2_1111_chunk']::text[] THEN RAISE EXCEPTION 'exact owned drop_chunks set mismatch'; END IF;END $guard$;
